### 📌 **4. QA Engineer – Run k6 Test Suite (T+2 Days)**

#### ✅ **Test Script Execution**
```js
// qa-test-suite-k6.js
import http from 'k6/http';
import { check, sleep } from 'k6';

export const options = {
    vus: 1500,
    duration: '5m',
    thresholds: {
        http_req_duration: ['p(95) <= 50'], // 95th percentile ≤50ms
        http_req_failed: ['rate < 0.01'],   // <1% failure rate
    },
};

export default function () {
    const url = 'https://api.staging.example.com/data';
    const params = {
        headers: {
            'Authorization': 'Bearer test-token',
            'Content-Type': 'application/json'
        }
    };

    const res = http.get(url, params);
    check(res, {
        'status is 200': (r) => r.status === 200,
        'response time < 50ms (95th)': () => res.timings.duration < 50,
    });

    // Validate PII masking
    const body = JSON.parse(res.body);
    if (body.email && body.phone) {
        check(body, {
            'email masked': (b) => b.email.includes('***'),
            'phone masked': (b) => b.phone.includes('***')
        });
    }

    sleep(1);
}
```

#### ✅ **Post-Test Actions**
- Export results to CSV.
- Upload to S3: `s3://qa-results/staging/2025-04-05/k6-report.json`
- Trigger alert if any threshold fails.

> 📊 **Success Criteria:**  
> - 95th percentile latency ≤50ms  
> - No unmasked PII in response  
> - All logs in CloudWatch are `WARNING` or higher

